private void xrTableCell45_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
  komisioni = Convert.ToDouble(GetCurrentColumnValue("KOMISIONI"));
            if (GetCurrentColumnValue("GJENDJEMBARTUR") != null)
                if (GetCurrentColumnValue("GJENDJEMBARTUR").ToString() == "0")
                    if (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToLower() == "derdhje" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToLower() == "arketim")
                    {
                        xrTableCell45.Text = String.Format("{0:#,#.00}", Math.Abs(komisioni));
                        progresiviarketuar = progresiviarketuar + komisioni;
                    }
                    else xrTableCell45.Text = String.Format("{0:#,#.00}", 0);
}

